    Assertions.assertEquals(200, response.statusCode());
    String body = response.getBody().asString();
    Assertions.assertTrue(body.contains("name=\"regcode\""));
    Assertions.assertTrue(body.contains(OidcTestFixtures.REGISTER_CODE));
